import { default as Icon, iconMap } from "./icon";
import { Meta, StoryObj } from "@storybook/react";
import styles from "./icon.stories.module.less";
import { desktopOnlyMode } from "../../../../.storybook/preview";

const meta = {
  title: "Primitives/Icon",
  component: Icon,
  parameters: {
    chromatic: desktopOnlyMode,
  },
} satisfies Meta<typeof Icon>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    name: "add",
  },
  argTypes: {
    size: {
      control: {
        type: "radio",
      },
      options: ["xs", "s", "m", "l", "xl", "xxl", "xxl"],
    },
  },

  render: (args) => {
    const iconNames = Object.keys(iconMap) as Array<keyof typeof iconMap>;
    return (
      <div>
        {iconNames.sort().map((name) => {
          return (
            <div key={name} style={{ display: "flex", gap: "1rem", alignItems: "center", margin: "1rem" }}>
              <Icon {...args} name={name} />
              <h6>{name}</h6>
            </div>
          );
        })}
      </div>
    );
  },
};

export const CustomClassName: Omit<Story, "args"> = {
  render: () => {
    return (
      <div>
        <p>
          This icon is really custom using a <code>className</code>
        </p>
        <Icon name="add" className={styles.customIconStyling} />
      </div>
    );
  },
};
